BEGIN;
SET LOCAL lock_timeout = '5s';
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname='code_symbols_kind_check'
             AND pg_get_constraintdef(oid) LIKE '%doc%') THEN
    RAISE EXCEPTION '254: kind already permits doc -- nothing to do';
  END IF;
END $$;
ALTER TABLE code_symbols DROP CONSTRAINT code_symbols_kind_check;
ALTER TABLE code_symbols ADD CONSTRAINT code_symbols_kind_check
  CHECK (kind = ANY (ARRAY['func','method','struct','interface','alias','type','var','const','doc']));
COMMIT;
-- No new index: idx_code_symbols_body_trgm already covers body, which is where
-- section text lands, and the content search added in 243/a4f06f83a already ORs
-- body with content. Markdown rides the mechanism layer 1 built.

// kindDoc is the new CHECK value; a const so the Go and the migration cannot drift.
const kindDoc = "doc"

// flattenMarkdown walks `root` for the configured prose sources and returns one
// row per heading-section. Body = the section text; content = heading + path ONLY.
func flattenMarkdown(root string, globs []string, logger *zap.Logger) []symbolRow {
    // for each matching file:
    //   split on /^#{1,6} / boundaries, recording [start,end] line spans
    //   symbol := heading text, trimmed of leading #s
    //   on a repeat heading WITHIN THE SAME FILE: symbol += fmt.Sprintf(" (#%d)", n)
    //   body   := analysis.SliceLines(src, start, end)   // the SAME slicer as code
    //   content:= composeDocContent(symbol, path)         // small: embedded + hashed
    //   rows = append(rows, symbolRow{kind: kindDoc, ...})
    // log files_read / sections / slice_errors, and WARN when sections==0,
    // exactly as flattenSymbols does -- a silent zero here is the failure mode.
}

func composeDocContent(heading, path string) string {
    return kindDoc + " " + heading + "\n" + path
}
// Deliberately NOT the section text. Same invariant 243_..._VERIFY.sql asserts
// for code rows: content_hash must equal sha256(content) with body absent.

rows := flattenSymbols(out, logger)
docGlobs := configStringSlice(config, "doc_globs", defaultDocGlobs)
docRows := flattenMarkdown(out.Root, docGlobs, logger)
rows = append(rows, docRows...)
// ... existing loop unchanged ...
return map[string]interface{}{..., "doc_sections": len(docRows), ...}

var defaultDocGlobs = []string{
    "bugs_open/*.md",
    "bugs_closed/*.md",
    "docs/agent_docs/docs024_key_docs_latest/WRONG_CALLS.md",
    "docs/agent_docs/docs024_key_docs_latest/016b_debugging_guide_8_consolidated.md",
